"""Run once on Colab to overwrite stale bootstrap.py / runtime.py."""
from __future__ import annotations

import base64
import sys
from pathlib import Path

BOOTSTRAP_B64 = ""
RUNTIME_B64 = ""


def main() -> None:
    here = Path("/content/ai_free_providers/host/colab")
    if not here.is_dir():
        # fallback: next to this file
        here = Path(__file__).resolve().parent if "__file__" in dir() else Path.cwd()

    boot = here / "bootstrap.py"
    run = here / "runtime.py"
    boot.write_bytes(base64.b64decode(BOOTSTRAP_B64))
    run.write_bytes(base64.b64decode(RUNTIME_B64))
    print("Wrote", boot, "bytes", boot.stat().st_size)
    print("Wrote", run, "bytes", run.stat().st_size)

    for name in list(sys.modules):
        if name in {"bootstrap", "runtime"} or name.startswith("bootstrap.") or name.startswith("runtime."):
            del sys.modules[name]

    sys.path.insert(0, str(here))
    import bootstrap

    print("has install_all:", hasattr(bootstrap, "install_all"))
    if not hasattr(bootstrap, "install_all"):
        raise SystemExit("Sync failed — install_all still missing")
    print("OK — re-run the READY cell")


main()
